{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "α-Allocryptopine, a protopine-type alkaloid sharing the same N-methylated tetracyclic scaffold and ketone as the query, was detected in rat CSF after systemic administration, directly demonstrating BBB passage; its high Morgan similarity makes this the strongest transferable evidence.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Corynoline, a related isoquinoline alkaloid with methylenedioxy groups, showed relatively high brain concentrations in mice, supporting meaningful CNS access for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "(+)-Bicuculline, which contains methylenedioxy and isoquinoline motifs, penetrated the brain in a dose-dependent manner in rats, further supporting CNS access for related alkaloids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "GYKI-52466, a less similar methylenedioxy-containing compound, had only about 4% steady-state brain-to-plasma ratio, indicating that methylenedioxy alone does not guarantee penetration; however, its low similarity and different scaffold limit transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: the query is a protopine-type alkaloid with favorable passive BBB properties and strong transferable evidence from close analogues (allocryptopine, corynoline, bicuculline) showing CSF/brain penetration. The few low-permeability records are structurally distant and do not override the consistent supportive evidence.",
  "evidence_gaps": [
    "No direct quantitative brain/plasma or CSF/plasma ratio is available for the exact query molecule; most evidence is qualitative detection in brain or CSF.",
    "Efflux liability (e.g., P-gp/BCRP) is not directly measured for protopine itself, though the query's neutral fraction and rigid lipophilic scaffold suggest limited transporter risk.",
    "Methylenedioxy groups may be metabolically labile, which could affect systemic exposure but not intrinsic BBB passage."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

